// The trace event for this decision: what the agent decided, what it saw (its
// full context) and what the LLM call cost (model, attempts, time, prompt size).
// Token counts stay inside the LangChain sub-node, which workflow code cannot
// read, so the exact prompt size in characters is logged instead.
// data, ($('Note failure').isExecuted && $('Note failure').last().json.use_fallback) ? ($env.GROQ_FALLBACK_MODEL || 'openai/gpt-oss-20b') : ($env.GROQ_MODEL || 'openai/gpt-oss-120b') and 3230 are filled in by build_workflows.py;
// ($('Note failure').isExecuted && $('Note failure').last().json.use_fallback) ? ($env.GROQ_FALLBACK_MODEL || 'openai/gpt-oss-20b') : ($env.GROQ_MODEL || 'openai/gpt-oss-120b') is the same expression that picks the chat model (primary or fallback).
const failed = $('Note failure').isExecuted ? $('Note failure').last().json : null;
const context = $('Input').first().json.context;

return [{
  json: {
    agent: 'data',
    kind: 'decision',
    content: $json.output,
    reasoning: $json.output.reasoning,
    context,
    meta: {
      model: ($('Note failure').isExecuted && $('Note failure').last().json.use_fallback) ? ($env.GROQ_FALLBACK_MODEL || 'openai/gpt-oss-20b') : ($env.GROQ_MODEL || 'openai/gpt-oss-120b'),
      fallback_reason: failed?.use_fallback ? failed.fallback_reason : null,
      llm_attempts: (failed?.failures ?? 0) + 1,
      elapsed_ms: Date.now() - $('Start clock').first().json.started_ms,
      prompt_chars: 3230 + 'Context:\n'.length + JSON.stringify(context).length,
    },
  },
}];

// Counts failed LLM calls in this decision ($runIndex grows on each pass) and
// decides whether the next call switches to the fallback model.
// n8n hands this branch only its own summary of the Groq error ("The service is
// receiving too many requests from you"), not Groq's text, so a spent daily quota
// cannot be told apart from the per-minute limit by its message. It is told apart
// by persistence instead: the per-minute window has passed after one wait, the
// daily one has not. A missing or withdrawn model switches at once. The switch
// sticks for the rest of this decision.
const text = (error) => String(error?.message ?? error ?? '');
const RATE_LIMIT = /too many requests|rate limit|tokens per day|\(TPD\)/i;
const error = $json.error;
const message = text(error);
const modelGone = /could not be found|model_not_found|decommissioned|does not exist/i.test(message);
const previous = $runIndex > 0 ? $('Note failure').last().json : null;
const limitPersisted = RATE_LIMIT.test(message) && previous !== null && RATE_LIMIT.test(text(previous.error));

let reason = previous?.use_fallback ? previous.fallback_reason : null;
if (!reason && modelGone) reason = `model unavailable: ${message.slice(0, 200)}`;
if (!reason && limitPersisted) reason = `rate limit persisted after waiting (daily quota): ${message.slice(0, 200)}`;

return [{ json: { failures: $runIndex + 1, error, use_fallback: reason !== null, fallback_reason: reason } }];
